// Literal port of the team's Casa3DSDK (module house/stairs). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installHouseStairs(K: Kernel, shared: Shared): void {
  const { rectsOf, Y0, boxC, bx, cursor, flights, stairFootprint, structurePiece } = K;
  const sh = (...a: any[]): any => K.sh(...a);
  function buildStairs() {
    const R = shared.ctx.r; shared.ctx.stairs = [];
    for (const vo of flights()) {
      const m = vo.m, f = vo.from, Dr = m.d - (vo.LP || 0); cursor.group = 'f' + f; cursor.pc = structurePiece('stairs_' + vo.from + '_' + vo.to); const y0 = Y0(f), H = Y0(m.link.to) - y0, n = Math.max(8, Math.round(H / 0.18)), c = Math.cos(m.ry), s = Math.sin(m.ry);
      const wood = shared.ctx.colors.wood != null ? shared.ctx.colors.wood : 0x8a6a48, under = sh(wood, 0.7);
      const P = (lx, lz) => [m.x + lx * c + lz * s, m.z - lx * s + lz * c];
      const boxL = (mat, lx, y, lz, w, h, d, color, rx = 0) => { const [px, pz] = P(lx, lz); boxC(mat, px, y, pz, w, h, d, color, rx, m.ry, 0); };
      for (let i = 0; i < n; i++) {
        const top = (i + 1) * H / n, lz = m.d / 2 - (i + 0.5) * Dr / n;
        boxL('wood', 0, y0 + top - 0.03, lz, m.w - 0.08, 0.06, Dr / n + 0.03, wood); // step
        boxL('wood', 0, y0 + top - H / n / 2, lz + Dr / n / 2, m.w - 0.08, H / n, 0.025, under); // riser
      }
      const L = Math.hypot(Dr, H), al = Math.atan2(H, Dr), lzc = m.d / 2 - Dr / 2;
      for (const sd of [-1, 1]) {
        boxL('wood', sd * (m.w / 2 - 0.02), y0 + H / 2 - 0.12, lzc, 0.04, 0.24, L, under, al);
        const side = sd; // handrail on the side opposite the wall (local +x side) and on the other
        boxL('metal', side * (m.w / 2 - 0.02), y0 + H / 2 + 0.9, lzc, 0.04, 0.04, L, 0x4a4a4e, al);
        for (let k = 0; k <= 4; k++) { const t = k / 4, lz = m.d / 2 - t * Dr; boxL('metal', side * (m.w / 2 - 0.02), y0 + t * H + 0.45, lz, 0.03, 0.9, 0.03, 0x4a4a4e); }
      }
      cursor.pc = null; shared.ctx.stairs.push({ m, f, to: vo.to, y0, H, rect: stairFootprint(m), landingPoint: (vo.LP || 0) / m.d });
    }
  }
  function elevator() {
    const R = shared.ctx.r;
    for (const c of R.rooms.filter(c => c.type === 'elevator' && c.floor === 0)) {
      cursor.group = 'f0'; const [u0, v0, u1, v1] = rectsOf(c)[0], y0 = Y0(0);
      bx('metal', u0 + 0.15, y0 + 0.05, v0 + 0.15, u1 - 0.15, y0 + 2.3, v1 - 0.15, 0x9aa0a6); bx('emissive', u0 + 0.3, y0 + 2.28, v0 + 0.3, u1 - 0.3, y0 + 2.3, v1 - 0.3, shared.ctx.night ? 0xfff0c8 : 0xcfd2d4);
      for (const f of R.floors) { const yy = Y0(f.index); cursor.group = 'f' + f.index; bx('metal', u0 + 0.05, yy, (v0 + v1) / 2 - 0.4, u0 + 0.09, yy + 2.1, (v0 + v1) / 2 + 0.4, 0x8a9096); }
    }
  }
  Object.assign(K, { buildStairs, elevator });
}
